import {attachPathFollow,detachPathFollow,pathCandidates} from '../animation/path-follow.js';
import {pathFollowSettings,validPathFollowValue,pathFollowRanges} from '../animation/path-follow-settings.js';
import {evaluated,setProperty} from '../animation/evaluate.js';
import {find,isLocked,uid} from '../document/model.js';
import {escape} from '../renderer/svg.js';
import {ImmediateEffectSession,bindImmediateEffect} from './immediate-effect.js';

export const pathFollowLabels={followProgress:'Path progress',followOffset:'Path offset',followNoiseAmount:'Path noise amount',followNoiseSize:'Path noise size',followNoiseSpeed:'Path noise speed',followNoiseSeed:'Path noise seed'};
const sessions=new WeakMap();
export function animatePathFollow(project,id,time,duration){
 const n=find(project,id);if(!n?.pathFollow?.enabled||isLocked(project,id)||n.reference)throw Error('Attach an unlocked shape or group to a path first.');
 const start=Math.round(time*project.fps)/project.fps,frames=Math.round(duration*project.fps),end=start+frames/project.fps;
 if(!Number.isFinite(start)||start<0||!Number.isFinite(frames)||frames<1||end>600)throw Error('Choose a duration of at least one frame, within the 10 minute composition limit.');
 const active=(n.blocks||[]).filter(b=>b.tracks&&start>=b.start&&start<b.end),block=active.findLast(b=>Object.hasOwn(b.tracks,'followProgress'))||active.at(-1);
 if(block&&end>block.end-1/project.fps+.00001)throw Error('The duration must fit inside the current sequence block. Shorten it or stretch the block first.');
 if((n.blocks||[]).some(b=>b!==block&&b.tracks?.followProgress?.length&&b.start<=end&&b.end>start))throw Error('Another sequence block controls path progress in this range. Choose a duration inside one block or move the playhead to an unoccupied range.');
 if((n.blockCuts||[]).some(c=>Object.hasOwn(c.values,'followProgress')&&c.start<end&&c.end>start))throw Error('This range includes a cut in path progress. Choose an uncut range for the new travel.');
 const tracks=block?.tracks||n.tracks,prior=tracks.followProgress||[],before=evaluated(n,Math.max(0,start-1/project.fps)).followProgress;
 // Base animation holds its final key; bounded existing clips retain their established outside-range behavior.
 const keys=[{id:uid(),time:start,value:0,easing:'linear'},{id:uid(),time:end,value:100,easing:'linear'}];
 const retained=prior.filter(k=>k.time<start-.00001||k.time>end+.00001);if(start>(block?.start||0)&&!retained.some(k=>Math.abs(k.time-(start-1/project.fps))<.00001))retained.push({id:uid(),time:start-1/project.fps,value:before,easing:'hold'});
 tracks.followProgress=[...retained,...keys].sort((a,b)=>a.time-b.time);if(block&&!block.props.includes('followProgress'))block.props.push('followProgress');
 const previous=project.duration;project.duration=Math.max(previous,end);
 if(project.playback&&project.playback.end===previous)project.playback.end=project.duration;
 return {keys,start,end,blockId:block?.id};
}
export function createPathFollowSession(a,id){
 const read=()=>{const n=find(a.doc,id);return {...pathFollowSettings(evaluated(n,a.time)),enabled:!!n.pathFollow?.enabled,orient:!!n.pathFollow?.orient,reverse:!!n.pathFollow?.reverse,loop:!!n.pathFollow?.loop};};
 const session=new ImmediateEffectSession(a,id,'Path follow',read,(values,prop,time)=>{const n=find(a.doc,id);if(!n?.pathFollow)return;if(Object.hasOwn(pathFollowRanges,prop))setProperty(n,prop,values[prop],time);else n.pathFollow[prop]=values[prop];},(prop,value)=>['enabled','orient','reverse','loop'].includes(prop)?typeof value==='boolean':validPathFollowValue(prop,value),'enabled');
 const originalSet=session.set.bind(session);session.set=(prop,value)=>a.selected?.length!==1||a.selected[0]!==id||!find(a.doc,id)?.pathFollow?false:originalSet(prop,value);return session;
}
export function refreshPathFollowEditor(a){const entry=sessions.get(a);if(!entry)return;entry.session?.refresh();if(a.doc!==entry.doc||a.selected.length!==1||a.selected[0]!==entry.id||!find(a.doc,entry.id)||entry.session?.closed){entry.dialog.close();return;}entry.sync();}
export function showPathFollow(a,id=a.selected[0]){
 const n=find(a.doc,id);if(!n||n.reference)return a.toast('Select a shape or grouped character first.');
 sessions.get(a)?.dialog.close();a.properties?.flush();a.pause();a.selected=[id];a.render();
 const candidates=pathCandidates(a.doc,id),locked=isLocked(a.doc,id),attached=!!n.pathFollow,doc=a.doc,d=document.createElement('dialog');d.id='path-follow-editor';d.className='path-follow-editor';d.dataset.modal='false';d.dataset.popupCategory='animation';d.setAttribute('aria-labelledby','path-follow-title');
 const field=(prop,label,min,max,step=1)=>`<label class="path-follow-field"><span>${label}</span><input data-follow-value="${prop}" type="number" min="${pathFollowRanges[prop][0]}" max="${pathFollowRanges[prop][1]}" step="${step}" aria-label="${label}"><input data-follow-value="${prop}" type="range" min="${min}" max="${max}" step="${step}" aria-label="${label} slider"></label>`;
 d.innerHTML=`<header><strong id="path-follow-title">Follow path · ${escape(n.name)}</strong><button data-follow-close aria-label="Close path follow">×</button></header><div class="path-follow-body"><fieldset ${locked?'disabled':''}><section><h3>Path connection</h3><label>Follow this path<select data-follow-target aria-label="Path to follow"><option value="">Choose a path…</option>${candidates.map(c=>`<option value="${escape(c.id)}" ${n.pathFollow?.targetId===c.id?'selected':''}>${escape(c.name)}</option>`).join('')}</select></label><div class="path-follow-actions"><button data-follow-attach ${!candidates.length?'disabled':''}>${attached?'Change path':'Attach to path'}</button>${attached?'<button data-follow-detach>Detach</button>':''}</div><p class="subtle">${candidates.length?'Draw or edit the guide with Path or Pencil. The shape’s pivot follows it; a group moves as one character.':'Draw a path or pencil line first, then select the shape or group you want to move.'}</p>${attached?'<p class="subtle">Detach keeps the current pose. Hide the guide layer to leave only the moving artwork visible.</p>':''}</section>${attached?`<section><h3>Travel</h3>${field('followProgress','Progress (%)',0,100,.1)}${field('followOffset','Offset (px)',-300,300,1)}<div class="path-follow-switches"><label><input type="checkbox" data-follow-value="orient"> Face path direction</label><label><input type="checkbox" data-follow-value="reverse"> Reverse direction</label><label><input type="checkbox" data-follow-value="loop"> Wrap progress</label></div><p class="subtle">100% reaches the end. Wrap lets values above 100% repeat; use a closed path for a seamless loop. Rotation adds a facing offset. Existing X/Y animation adds movement relative to the guide.</p></section><section><h3>Noise along path</h3>${field('followNoiseAmount','Amount (px)',0,200,1)}${field('followNoiseSize','Size (px)',2,500,1)}${field('followNoiseSpeed','Noise speed',-5,5,.1)}<label class="path-follow-seed">Pattern seed<input data-follow-value="followNoiseSeed" type="number" min="-1000000" max="1000000" step="1"></label><p class="subtle">Amount 0 stays on the guide. Larger size spreads out the bends; speed animates the noise.</p></section><section><h3>Animate</h3><label>Travel duration (seconds)<input data-follow-duration type="number" min="${1/a.doc.fps}" max="600" step="${1/a.doc.fps}" value="2"></label><button data-follow-animate>Animate along path</button><p class="subtle">Adds progress keys from 0 to 100% at the playhead. Other properties and keys outside this range stay intact. Existing sequence blocks limit the duration. Edit its timing and easing in the sequence or graph.</p></section>`:''}</fieldset></div><footer><output data-follow-status></output><div class="path-follow-actions">${attached?'<button data-follow-play>Play</button><button data-follow-stop>Stop</button>':''}<button data-follow-close>Done</button></div></footer>`;
 if(attached){const body=d.querySelector('.path-follow-body'),fieldset=d.querySelector('fieldset'),sections=[...fieldset.children],tabs=document.createElement('nav');tabs.className='path-follow-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','Path follow sections');tabs.innerHTML=[['path','Path'],['noise','Noise'],['timing','Timing']].map(([key,label],i)=>`<button role="tab" id="follow-tab-${key}" data-follow-tab="${key}" aria-selected="${i===0}" aria-controls="follow-panel-${key}" tabindex="${i===0?0:-1}">${label}</button>`).join('');body.before(tabs);for(const [key,indexes] of [['path',[0,1]],['noise',[2]],['timing',[3]]]){const panel=document.createElement('div');panel.id='follow-panel-'+key;panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby','follow-tab-'+key);panel.hidden=key!=='path';indexes.forEach(i=>panel.append(sections[i]));fieldset.append(panel);}const select=(key,focus=false)=>{for(const tab of tabs.children){const current=tab.dataset.followTab===key;tab.setAttribute('aria-selected',current);tab.tabIndex=current?0:-1;if(current&&focus)tab.focus();}for(const panel of fieldset.querySelectorAll('[role=tabpanel]'))panel.hidden=panel.id!=='follow-panel-'+key;body.scrollTop=0;};tabs.onclick=e=>{const button=e.target.closest('[data-follow-tab]');if(button)select(button.dataset.followTab);};tabs.onkeydown=e=>{const button=e.target.closest('[data-follow-tab]');if(!button||!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const keys=['path','noise','timing'],index=keys.indexOf(button.dataset.followTab);select(keys[e.key==='Home'?0:e.key==='End'?2:(index+(e.key==='ArrowLeft'?-1:1)+3)%3],true);};}
 document.body.append(d);const session=attached?createPathFollowSession(a,id):null;
 const sync=()=>{const node=find(a.doc,id);if(!node)return;const values=session?.values;for(const input of d.querySelectorAll('[data-follow-value]')){if(document.activeElement===input)continue;const value=values?.[input.dataset.followValue];if(input.type==='checkbox')input.checked=!!value;else input.value=value??'';}d.querySelector('[data-follow-play]')?.replaceChildren(document.createTextNode(a.playing?'Pause':'Play'));d.querySelector('[data-follow-status]').textContent=(locked?'Layer locked · ':'')+'Frame '+Math.round(a.time*a.doc.fps)+(attached?' · Changes apply immediately':'');d.querySelector('[data-follow-attach]').disabled=locked||!d.querySelector('[data-follow-target]').value;};
 const valid=()=>a.doc===doc&&a.selected.length===1&&a.selected[0]===id&&find(doc,id)&&!isLocked(doc,id);
 const action=(label,fn)=>{if(!valid()){d.close();return;}d.close();a.mutate(label,fn);if(find(a.doc,id))showPathFollow(a,id);};
 d.querySelector('[data-follow-target]').onchange=sync;
 d.querySelector('[data-follow-attach]').onclick=()=>{const target=d.querySelector('[data-follow-target]').value;if(target)action('Attach to path',()=>attachPathFollow(a.doc,id,target,a.time));};
 d.querySelector('[data-follow-detach]')?.addEventListener('click',()=>action('Detach from path',()=>detachPathFollow(a.doc,id,a.time)));
 d.querySelector('[data-follow-animate]')?.addEventListener('click',()=>{const duration=Number(d.querySelector('[data-follow-duration]').value);action('Animate along path',()=>{const result=animatePathFollow(a.doc,id,a.time,duration);a.keyIds=new Set(result.keys.map(k=>k.id));a.timeline.collapsed.delete(id);a.timeline.expandedLayers.add(id);a.timeline.blockSelection=result.blockId?{object:id,id:result.blockId}:null;if(result.blockId)a.timeline.expandedBlocks.add(result.blockId);});});
 d.addEventListener('input',e=>{const input=e.target,prop=input.dataset.followValue;if(!prop||!session)return;const value=input.type==='checkbox'?input.checked:input.value===''?NaN:Number(input.value);a.pause();if(session.set(prop,value)){a.renderStage();sync();}});
 d.querySelector('[data-follow-play]')?.addEventListener('click',()=>{session.flush();a.safe(()=>a.play());sync();});d.querySelector('[data-follow-stop]')?.addEventListener('click',()=>{session.flush();a.seek(0);sync();});
 if(session)bindImmediateEffect(d,session);d.querySelectorAll('[data-follow-close]').forEach(button=>button.onclick=()=>d.close());d.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();e.stopPropagation();d.close();}});d.addEventListener('close',()=>{session?.cancel();if(sessions.get(a)?.dialog===d)sessions.delete(a);d.remove();},{once:true});sessions.set(a,{dialog:d,session,doc,id,sync});sync();d.show();return d;
}
